<script setup lang="ts">
import { computed, ref } from 'vue'; import { useWorkspace } from '../stores/workspace'
const ws=useWorkspace(),category=ref('全部'),period=ref('全部'),query=ref('');const money=(n:number)=>`${n<0?'−':'+'}¥${(Math.abs(n)/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}`
const rows=computed(()=>ws.transactions.filter(t=>(category.value==='全部'||t.category===category.value)&&(period.value==='全部'||t.date.startsWith(period.value))&&t.merchant.includes(query.value)))
const income=computed(()=>rows.value.filter(t=>t.amount>0).reduce((a,t)=>a+t.amount,0)),expense=computed(()=>-rows.value.filter(t=>t.amount<0).reduce((a,t)=>a+t.amount,0))
</script>
<template><div class="page-intro"><div><span class="eyebrow">SYNTHETIC LEDGER</span><h1>账单分析</h1><p>合成演示流水 · 统计按已选筛选条件计算</p></div></div><div class="grid bills-metrics"><article class="card compact-stat"><small>收入 / 退款</small><b class="positive">¥{{(income/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}}</b></article><article class="card compact-stat"><small>支出</small><b>¥{{(expense/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}}</b></article><article class="card compact-stat"><small>净额</small><b>{{money(income-expense)}}</b></article></div><section class="card table-card"><div class="filters"><select v-model="period"><option>全部</option><option value="2026-10">2026年10月</option><option value="2026-09">2026年9月</option></select><select v-model="category"><option>全部</option><option>餐饮</option><option>工资</option><option>订阅</option><option>交通</option><option>购物</option><option>退款</option></select><input v-model="query" placeholder="搜索商户"></div><div class="ledger-table"><div class="ledger-row ledger-head"><span>日期</span><span>商户</span><span>类别</span><span>金额</span></div><div v-for="(t,i) in rows" :key="i" class="ledger-row"><span>{{t.date}}</span><b>{{t.merchant}}</b><span>{{t.category}}</span><b :class="t.amount>0?'positive':''">{{money(t.amount)}}</b></div><div v-if="!rows.length" class="empty-state">没有符合筛选条件的流水</div></div><div class="notice">演示数据；真实账单需接入银行只读接口。退款与收入依数据类别分别统计。</div></section></template>
